-- [ HEARTBEAT CACHE SYNC ]
game:GetService('RunService').Heartbeat:Connect(function(dt)
    for i = 1, #SECURE_REGISTER do
        if SECURE_REGISTER[i] and SECURE_REGISTER[i].ACTIVE then
            SECURE_REGISTER[i].TICK = SECURE_REGISTER[i].TICK + dt
            if SECURE_REGISTER[i].TICK > 60 then
                SECURE_REGISTER[i].TICK = 0
                SECURE_REGISTER[i].STATUS = 'CYCLED'
            end
        end
    end
end)

